script:
function comicId(url, fallback) {
  var value = fallback || (url.match(/\/([0-9]+)(?:\/|$)/) || [])[1];
  var id = Number(value);
  if (!Number.isInteger(id) || id < 1 || id === 404) throw new Error('xkcd 编号无效；404 是作者故意保留的空章');
  return id;
}
async function comic(id) {
  var response = await triomi.fetch('https://xkcd.com/' + (id ? id + '/' : '') + 'info.0.json');
  if (response.status !== 200) throw new Error('xkcd HTTP ' + response.status);
  var result = JSON.parse(response.body);
  if (!result || !Number.isInteger(result.num) || !result.title || !/^https:\/\/imgs\.xkcd\.com\//.test(result.img || ''))
    throw new Error('xkcd 返回了无法识别的漫画元数据');
  return result;
}
function itemFor(value) {
  return {remoteId: String(value.num), title: value.title, url: 'https://xkcd.com/' + value.num + '/',
    coverUrl: value.img, author: 'Randall Munroe', description: value.alt || '', tags: ['英文', '科学', '条漫']};
}
async function discover(url, page) {
  if (!Number.isInteger(page) || page < 1) throw new Error('xkcd 分页无效');
  var latest = await comic(null);
  var start = latest.num - (page - 1) * 20;
  var ids = [];
  for (var id = start; id > Math.max(0, start - 20); id--) {
    if (id !== 404) ids.push(id);
  }
  var items = [];
  for (var offset = 0; offset < ids.length; offset += 4) {
    var batch = await Promise.all(ids.slice(offset, offset + 4).map(async function(id) {
      return itemFor(id === latest.num ? latest : await comic(id));
    }));
    items = items.concat(batch);
  }
  return items;
}
async function search(keyword, page) {
  if (page > 1) return [];
  var query = String(keyword || '').trim();
  if (!query) return discover('https://xkcd.com/info.0.json', 1);
  if (/^https:\/\/xkcd\.com\/[0-9]+\/?$/.test(query)) query = query.match(/\/([0-9]+)/)[1];
  if (!/^#?[0-9]+$/.test(query)) throw new Error('xkcd 官方接口不提供标题搜索，请输入漫画编号（例如 1）或 https://xkcd.com/1/');
  return [itemFor(await comic(comicId('', query.replace(/^#/, ''))))];
}
async function detail(url, item) {
  var result = await comic(comicId(url, item && item.remoteId));
  return {item:itemFor(result), chapters:[{remoteId:String(result.num), title:result.title,
    url:'https://xkcd.com/' + result.num + '/', number:result.num,
    releaseDate:result.year + '-' + String(result.month).padStart(2,'0') + '-' + String(result.day).padStart(2,'0')}]};
}
async function content(url, chapter) {
  var result = await comic(comicId(url, chapter && chapter.remoteId));
  return {images:[result.img], headers:{Referer:'https://xkcd.com/'}};
}
